import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.yse_Y9k2.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"notion-seed","text":"The bill before the write.","tagline":"Declare your Notion databases in YAML. Before anything is written, see — in rows — what each change will cost your data.","actions":[{"theme":"brand","text":"Get started","link":"/installation"},{"theme":"alt","text":"GitHub","link":"https://github.com/tykok/notion-seed"}]},"features":[{"title":"Measured before written","details":"Every line of the plan says how many rows will lose their value — and how many will get a plausible, wrong one."},{"title":"Drift detection","details":"The state tells \\"the YAML changed\\" from \\"someone edited Notion by hand\\", and shows the second before the plan."},{"title":"A CI safeguard you choose","details":"plan --fail-on=<classes> stops the workflow on the changes you name, and nothing else."},{"title":"No refusal on principle","details":"It informs, you decide. Only what the API cannot express is withheld — with the manual steps to do it."}]},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),s={name:"index.md"};function d(i,e,r,h,l,c){return a(),o("div",null,[...e[0]||(e[0]=[n(`<h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to &quot;Why&quot;">​</a></h2><p>Notion ends up running your day: projects, tasks, docs, rituals. Managing a workspace by hand is already hard. Managing its databases is harder — rename an option, remove a status, and rows quietly change value. notion-seed is a small tool born from that.</p><p>Declaring a Notion workspace in files is not the hard problem. The hard problem is knowing what the API will do to your data when the declaration changes.</p><p>Six behaviors measured against the API, which a tool that just sends the request does not warn you about:</p><table tabindex="0"><thead><tr><th>Change</th><th>What the API does</th></tr></thead><tbody><tr><td>Rename an option (with its id)</td><td>Returns <code>200</code>, changes nothing</td></tr><tr><td>Remove a <code>select</code> option</td><td>The affected rows are emptied</td></tr><tr><td>Remove a <code>multi_select</code> option</td><td>The affected rows lose <strong>this value</strong> — they are emptied only if they held no other</td></tr><tr><td>Remove a <code>status</code> option</td><td><strong>Reassigns the rows to another option</strong>, without an error</td></tr><tr><td><code>multi_select</code> → <code>select</code></td><td><strong>Keeps only one value</strong> on rows that held several</td></tr><tr><td><code>select</code> → <code>multi_select</code></td><td>Recreates the options: a row keeps its value only if the YAML redeclares an option <strong>with the same name</strong>; the others are emptied</td></tr></tbody></table><p>Measured on 2026-09-24 against API <code>2025-09-03</code>, on populated rows — the last one on 2026-09-25.</p><p>Removing a <code>status</code> option and <code>multi_select</code> → <code>select</code> are the ones that justify the tool: the data is not lost, it is replaced by a plausible, wrong value, indistinguishable after the fact.</p><p><code>notion-seed</code> does not stop you. It tells you, <strong>before writing</strong>, how many rows are affected. A <code>status</code> option removed from the YAML, held by two rows:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ntn 0.22.11 — workspace Example Space (33333333-3333-4333-8333-333333333333)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Plan: 0 to add, 1 to change, 0 to destroy</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  ~ database.tasks  [silent rewrite]</span></span>
<span class="line"><span>      - option &quot;Fait&quot; (property &quot;Statut&quot;) — absent from the YAML: the API replaces the whole list of options  [silent rewrite]</span></span>
<span class="line"><span>          → 2 rows will be reassigned to another option, without a trace.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Impact: 2 values reassigned without a trace.</span></span></code></pre></div><p>The number is measured, not inferred: the same line would be classified <code>safe</code>, with <code>0 rows affected</code>, if nobody used that option. That is what a refusal on principle could not see, and why it was replaced by a measurement. What could not be counted — offline, or when the query fails — comes out as <code>unknown impact</code>, never as &quot;nothing to lose&quot;.</p><div class="tip custom-block"><p class="custom-block-title">You stay in charge</p><p>You are responsible for your database. notion-seed is responsible for what you know when you press enter. In CI, <a href="/notion-seed/commands#in-ci"><code>--fail-on</code></a> hands the decision to the workflow.</p></div><h2 id="what-the-api-cannot-do" tabindex="-1">What the API cannot do <a class="header-anchor" href="#what-the-api-cannot-do" aria-label="Permalink to &quot;What the API cannot do&quot;">​</a></h2><p>Two changes are not expressible, measured on 2026-09-24:</p><table tabindex="0"><thead><tr><th>Change</th><th>What the API does</th></tr></thead><tbody><tr><td>Rename an option</td><td>Returns <code>200</code>, changes nothing</td></tr><tr><td>Change an option&#39;s color</td><td>Returns <code>400</code>, whether the option is designated by its id or by its name, and the whole PATCH of the property fails</td></tr></tbody></table><p><code>notion-seed</code> therefore does not write them, and withholds the whole database as long as they are declared. The other databases of the plan are applied. See <a href="/notion-seed/commands#what-it-withholds">What it withholds</a> for the migration procedure and the number of rows it names.</p><h2 id="current-status" tabindex="-1">Current status <a class="header-anchor" href="#current-status" aria-label="Permalink to &quot;Current status&quot;">​</a></h2><p><code>apply</code> creates the databases that are declared and absent from Notion, updates the ones that already exist — name, description, icon and declared properties — and moves to the trash the ones the YAML no longer declares. The state is updated after each resource written. Two option changes, which the API cannot express, are withheld with the migration to do by hand, and <code>apply</code> exits with a non-zero code as long as they remain — see <a href="#what-the-api-cannot-do">What the API cannot do</a>.</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><code>init</code>, <code>version</code>, <code>plan</code>, <code>diff</code>, <code>import</code></td><td>available</td></tr><tr><td><code>apply</code></td><td>creations, updates and destructions — see <a href="/notion-seed/commands#apply">Applying</a></td></tr><tr><td>state file</td><td><code>notion-seed.state.json</code>, written by <code>import</code> and <code>apply</code></td></tr><tr><td><code>lifecycle.prevent_destroy</code> / <code>allow_data_loss</code></td><td>acknowledgements — see <a href="/notion-seed/yaml#lifecycle-acknowledgements">lifecycle</a></td></tr><tr><td><code>--fail-on</code></td><td>the CI safeguard — see <a href="/notion-seed/commands#in-ci">In CI</a></td></tr></tbody></table>`,18)])])}const w=t(s,[["render",d]]);export{u as __pageData,w as default};
